"""`lk shell-init zsh|bash` prints the shell integration; your rc file keeps one line:

    eval "$(lk shell-init zsh)"

It is generated, so it can never drift from the installed LOOK, and it never
overwrites a command, alias or function you already have.
"""
from __future__ import annotations

from .paths import roots
from .settings import settings

CORE = r'''
# ---- LOOK {version} shell integration (generated by `lk shell-init {shell}`) ----
_look_bin="{lk}"

lk() {{
  local _h; _h="$(mktemp -t look-handoff.XXXXXX)" || return
  LOOK_HANDOFF="$_h" "$_look_bin" "$@"
  local _rc=$?
  if [ -s "$_h" ]; then
    local _d; _d="$(cat "$_h")"
    [ -d "$_d" ] && cd "$_d"
  fi
  rm -f "$_h"
  if [ -s "{command_handoff}" ]; then            # `lk commands` put a template on your prompt
    if [ -n "$ZSH_VERSION" ]; then print -z "$(cat "{command_handoff}")"; else cat "{command_handoff}"; echo; fi
    rm -f "{command_handoff}"
  fi
  return $_rc
}}

lo() {{ "$_look_bin" lo "$@"; }}
future-crash() {{ "$_look_bin" future-crash "$@"; }}

_look_define() {{
  # define a short name only when nothing else already owns it
  if ! type "$1" >/dev/null 2>&1; then eval "$1() {{ $2 \"\$@\"; }}"; fi
}}

# Background LO jobs finish while you work; say so at the next prompt.
_look_journal="{journal}"
_look_stamp="{stamp}"
_look_precmd() {{
  [ -f "$_look_journal" ] || return
  if [ ! -f "$_look_stamp" ] || [ "$_look_journal" -nt "$_look_stamp" ]; then
    "$_look_bin" _events 2>/dev/null
  fi
}}
'''

SHORT = r'''
_look_define fcr  future-crash
_look_define rst  future-crash
_look_define l    lk
_look_define ll   "lk detail"
_look_define ld   "lk dirs"
_look_define lf   "lk files"
_look_define lt   "lk tree"
_look_define lr   "lk recent"
_look_define lz   "lk size"
_look_define ff   "lk find"
_look_define lcp  "lk cp"
_look_define lmv  "lk mv"
_look_define lrm  "lk rm"
_look_define lmk  "lk mk"
_look_define mm   "lk media toggle"
_look_define mn   "lk media next"
_look_define mp   "lk media prev"
'''

ZSH = r'''
autoload -Uz add-zsh-hook 2>/dev/null && add-zsh-hook precmd _look_precmd
_look_complete() {
  local -a words; words=(${(f)"$("$_look_bin" _complete ${words[2,CURRENT-1]} 2>/dev/null)"})
  compadd -a words
}
(( $+functions[compdef] )) && compdef _look_complete lk
'''

BASH = r'''
case ";$PROMPT_COMMAND;" in *";_look_precmd;"*) ;; *) PROMPT_COMMAND="_look_precmd${PROMPT_COMMAND:+;$PROMPT_COMMAND}";; esac
_look_complete() {
  local cur="${COMP_WORDS[COMP_CWORD]}"
  COMPREPLY=( $(compgen -W "$("$_look_bin" _complete "${COMP_WORDS[@]:1:COMP_CWORD-1}" 2>/dev/null)" -- "$cur") )
}
complete -F _look_complete lk
'''


def script(shell: str, lk_path: str) -> str:
    from . import __version__
    shell = "bash" if shell == "bash" else "zsh"
    text = CORE.format(version=__version__, shell=shell, lk=lk_path, journal=roots.journal,
                       stamp=roots.runtime / "events.seen", command_handoff=roots.handoff / "command")
    if settings.get("shell.short_aliases"):
        text += SHORT
    text += ZSH if shell == "zsh" else BASH
    return text
